      "numero": 1,
      "ar": "الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ وَجَعَلَ الظُّلُمَٰتِ وَالنُّورَ ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ",
      "translit": "Al-ḥamdu lillāhi lladhī khalaqa s-samāwāti wal-ʾarḍa wajaʿala ẓ-ẓulumāti wan-nūra thumma lladhīna kafarū birabbihim yaʿdilūn",
