      "ar": "فَقَدْ كَذَّبُواْ بِالْحَقِّ لَمَّا جَاءَهُمْ فَسَوْفَ يَأْتِيهِمْ أَنبَـٰؤُاْ مَا كَانُواْ بِهِ يَسْتَهْزِءُونَ",
      "translit": "Faqad kadhdhabū bil-ḥaqqi lammā jāʾahum fasawfa yaʾtīhim anbāʾu mā kānū bihī yastahziʾūn",
