          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "De ki: \"Acele istediğiniz şey elimde olsaydı, benimle aranızdaki iş bitmiş olurdu.\" Allah zulmedenleri en iyi bilendir"
