    "declic_frequence": "faṭara (fendre, créer en faisant surgir du néant, racine ف-ط-ر) porte le sommet de la sourate (v.79) : après avoir vu l'astre, la lune et le soleil décliner, Abraham proclame wajjahtu wajhiya li-lladhī faṭara s-samāwāti wa-l-arḍ — « je tourne mon visage vers Celui qui a fait surgir les cieux et la terre ». Le Fāṭir n'est pas un démiurge qui façonne une matière préexistante : Il fend le néant pour en faire jaillir l'être. De la même racine vient la fiṭra, la nature originelle de l'homme : se tourner vers le Fāṭir, c'est simplement redevenir ce pour quoi l'on a été fendu du néant."
